1	// Per-suite fixture: a hermetic PDS plus an account that can drive the consent form.
2	//
3	// The PDS spawner, TLS proxy, mock plc.directory, and account ceremony are all reused from
4	// tools/mcp/test/harness.ts rather than duplicated — that module is already the second
5	// consumer's dependency (tools/mcp-sidecar imports it the same way), so this is an
6	// established seam rather than a new one.
7	//
8	// The one thing this fixture adds is the account's **password**. tools/mcp's `TestAccount`
9	// omits it (its suite authenticates with a session JWT), but the OAuth consent form needs a
10	// real credential, so provisioning is repeated here against interop's richer return value.
11	
12	import * as fs from 'node:fs';
13	import * as http from 'node:http';
14	import * as net from 'node:net';
15	import * as os from 'node:os';
16	import * as path from 'node:path';
17	
18	import { ADMIN_TOKEN, spawnPds, type SpawnedPds } from '../../mcp/test/harness.ts';
19	import { startMockPlc, type MockPlc } from './mock-plc.ts';
20	
21	export { ADMIN_TOKEN };
22	
23	/** An OS-assigned free port, so parallel test files never collide. */
24	function freePort(): Promise<number> {
25	  return new Promise((resolve, reject) => {
26	    const server = net.createServer();
27	    server.listen(0, '127.0.0.1', () => {
28	      const port = (server.address() as net.AddressInfo).port;
29	      server.close((err) => (err ? reject(err) : resolve(port)));
30	    });
31	  });
32	}
33	
34	export interface ClientHost {
35	  clientId: string;
36	  redirectUri: string;
37	  close: () => void;
38	}
39	
40	/**
41	 * Serve an OAuth client metadata document over plain-http loopback.
42	 *
43	 * The PDS resolves a URL-shaped `client_id` by fetching it, so a test client must actually be
44	 * published somewhere. Loopback is the spec's local-development exception and this server
45	 * accepts it (`auth/oauth_client_resolution.rs`: plain http is allowed for localhost /
46	 * 127.0.0.1 / ::1, and such clients are exempt from the reverse-FQDN redirect rule) — which
47	 * is what makes a hermetic third-party-client harness possible at all.
48	 */
49	export async function startClientHost(
50	  metadata: Record<string, unknown> = {},
51	): Promise<ClientHost> {
52	  const port = await freePort();
53	  const origin = `http://127.0.0.1:${port}`;
54	  const clientId = `${origin}/client-metadata.json`;
55	  const redirectUri = `${origin}/callback`;
56	  const document = {
57	    client_id: clientId,
58	    client_name: 'Custos OAuth conformance suite',
59	    redirect_uris: [redirectUri],
60	    grant_types: ['authorization_code', 'refresh_token'],
61	    response_types: ['code'],
62	    application_type: 'web',
63	    token_endpoint_auth_method: 'none',
64	    dpop_bound_access_tokens: true,
65	    scope: 'atproto transition:generic',
66	    ...metadata,
67	  };
68	
69	  const server = http.createServer((req, res) => {
70	    if (req.url?.startsWith('/client-metadata.json')) {
71	      res.writeHead(200, { 'content-type': 'application/json' });
72	      res.end(JSON.stringify(document));
73	      return;
74	    }
75	    // The redirect target: nothing follows it (the suite reads the Location header
76	    // directly), but answering keeps a stray follow from hanging.
77	    res.writeHead(204);
78	    res.end();
79	  });
80	  await new Promise<void>((resolve) => server.listen(port, '127.0.0.1', resolve));
81	  // `close()` alone waits for idle keep-alive sockets, which a client that reused a
82	  // connection leaves open — enough to hold `node --test` past the last assertion.
83	  return {
84	    clientId,
85	    redirectUri,
86	    close: () => {
87	      server.closeAllConnections();
88	      server.close();
89	    },
90	  };
91	}
92	
93	export interface ConformanceAccount {
94	  did: string;
95	  handle: string;
96	  email: string;
97	  /** The credential the consent form needs; interop sets it during the DID ceremony. */
98	  password: string;
99	}
100	
101	export interface Fixture {
102	  baseUrl: string;
103	  account: ConformanceAccount;
104	  /**
105	   * The directory the spawned PDS was pointed at, carrying the account's real DID document.
106	   * A client that resolves DIDs (the official SDK does) must be pointed here too.
107	   */
108	  plcUrl: string;
109	  stop: () => void;
110	}
111	
112	/**
113	 * Spawn a PDS and provision one account.
114	 *
115	 * One fixture per test *file*: interop's config module reads `EZPDS_BASE_URL` at first
116	 * import and caches it, so a second fixture in the same Node process would provision against
117	 * the first PDS. `node --test` gives each file its own process, which makes this safe as
118	 * long as the rule is honored.
119	 */
120	export async function startFixture(
121	  options: {
122	    /**
123	     * Override `oauth.access_token_ttl_secs`. Set this to a second or two to test what a
124	     * client sees once its token lapses, without the suite waiting out a real 15-minute
125	     * token. Tests that use it belong in their own file (see the one-fixture-per-file rule).
126	     */
127	    accessTokenTtlSecs?: number;
128	  } = {},
129	): Promise<Fixture> {
130	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'custos-oauth-conformance-'));
131	  const plc = await startMockPlc();
132	  let pds: SpawnedPds | undefined;
133	  try {
134	    // `spawnPds` runs the binary with a closed env allowlist and its cwd set to `dir`, so a
135	    // setting without an entry in that allowlist is reached by dropping a config file here —
136	    // the same escape hatch tools/mcp-sidecar uses for its agent_auth scopes.
137	    if (options.accessTokenTtlSecs !== undefined) {
138	      fs.writeFileSync(
139	        path.join(dir, 'pds.toml'),
140	        `[oauth]\naccess_token_ttl_secs = ${options.accessTokenTtlSecs}\n`,
141	      );
142	    }
143	    pds = await spawnPds({ dir, plcUrl: plc.url, agentAuthEnabled: false });
144	
145	    process.env.EZPDS_BASE_URL = pds.baseUrl;
146	    process.env.EZPDS_ADMIN_TOKEN = ADMIN_TOKEN;
147	    process.env.EZPDS_INTEROP_STATE_DIR = path.join(dir, 'interop-state');
148	    process.env.EZPDS_INTEROP_PACE_MS = '25';
149	
150	    const account = await import('ezpds-interop/src/account.js');
151	    const created = await account.createAccount({
152	      name: 'oauth-conformance',
153	      kind: 'ephemeral',
154	    });
155	    if (!created.password) {
156	      throw new Error(
157	        'interop account ceremony returned no password; the OAuth consent form cannot be ' +
158	          'driven without one (see tools/interop/src/account.js)',
159	      );
160	    }
161	
162	    // Publish the account's DID document so a client can resolve it. The PDS built this
163	    // document during the genesis ceremony and serves it back verbatim, so the directory
164	    // hands out the real thing rather than a test-shaped approximation.
165	    const described = await fetch(
166	      `${pds.baseUrl}/xrpc/com.atproto.repo.describeRepo?repo=${encodeURIComponent(created.did)}`,
167	    );
168	    if (!described.ok) {
169	      throw new Error(`could not read the account's DID document: HTTP ${described.status}`);
170	    }
171	    const { didDoc } = (await described.json()) as { didDoc?: unknown };
172	    if (!didDoc) {
173	      throw new Error('describeRepo returned no didDoc; the mock directory would serve nothing');
174	    }
175	    plc.register(created.did, didDoc);
176	
177	    const spawned = pds;
178	    return {
179	      baseUrl: spawned.baseUrl,
180	      plcUrl: plc.url,
181	      account: {
182	        did: created.did,
183	        handle: created.handle,
184	        email: created.email,
185	        password: created.password,
186	      },
187	      // Best-effort teardown: attempt every step even if an earlier one throws, because a
188	      // leaked pds child keeps `node --test` alive on an open handle.
189	      stop: () => {
190	        try {
191	          spawned.stop();
192	        } catch {
193	          /* already gone */
194	        }
195	        try {
196	          plc.close();
197	        } catch {
198	          /* already gone */
199	        }
200	        fs.rmSync(dir, { recursive: true, force: true });
201	      },
202	    };
203	  } catch (err) {
204	    try {
205	      pds?.stop();
206	    } catch {
207	      /* never started */
208	    }
209	    plc.close();
210	    throw err;
211	  }
212	}
