1	// A mock plc.directory that can actually answer a DID lookup.
2	//
3	// tools/mcp's stub answers every path with `{}`, which is all its suite needs: the PDS POSTs
4	// a genesis operation during account creation and never reads anything back. A real OAuth
5	// *client* is different — it resolves the `sub` DID it was handed, finds that DID's PDS, and
6	// checks the token really came from there. That is the whole point of the check (it stops a
7	// hostile authorization server minting tokens for someone else's account), so a client that
8	// performs it correctly cannot be tested against a directory that returns `{}`.
9	//
10	// This is a local variant rather than a change to the shared harness: two other suites depend
11	// on that module, and neither needs a stateful directory.
12	//
13	// The documents served here are not synthesized. The harness reads each one back from the PDS
14	// (`com.atproto.repo.describeRepo` returns `didDoc`) and registers it, so a client resolving a
15	// DID sees the same document the server would have published to the real directory.
16	
17	import * as http from 'node:http';
18	
19	export interface MockPlc {
20	  url: string;
21	  /** Publish a DID document, making `GET /{did}` resolvable. */
22	  register: (did: string, document: unknown) => void;
23	  close: () => void;
24	}
25	
26	export function startMockPlc(): Promise<MockPlc> {
27	  const documents = new Map<string, unknown>();
28	
29	  return new Promise((resolve) => {
30	    const server = http.createServer((req, res) => {
31	      const path = decodeURIComponent((req.url ?? '/').split('?')[0] ?? '/');
32	      const did = path.slice(1);
33	      const document = documents.get(did);
34	
35	      if (req.method === 'GET' && document) {
36	        res.writeHead(200, { 'content-type': 'application/json' });
37	        res.end(JSON.stringify(document));
38	        return;
39	      }
40	      if (req.method === 'GET' && did.startsWith('did:')) {
41	        // An unregistered DID genuinely does not exist as far as this directory is concerned;
42	        // 404 is what the real one returns, and answering `{}` would turn a wiring mistake
43	        // into a confusing parse error inside the client instead.
44	        res.writeHead(404, { 'content-type': 'application/json' });
45	        res.end(JSON.stringify({ message: 'DID not registered in the mock directory' }));
46	        return;
47	      }
48	      // Everything else — notably the genesis-operation POST the PDS makes during account
49	      // creation — keeps the stub's accept-everything behaviour.
50	      res.writeHead(200, { 'content-type': 'application/json' });
51	      res.end('{}');
52	    });
53	
54	    server.listen(0, '127.0.0.1', () => {
55	      const address = server.address() as { port: number };
56	      resolve({
57	        url: `http://127.0.0.1:${address.port}`,
58	        register: (did, document) => documents.set(did, document),
59	        close: () => {
60	          // Idle keep-alive sockets would otherwise keep the test process alive.
61	          server.closeAllConnections();
62	          server.close();
63	        },
64	      });
65	    });
66	  });
67	}
