1	// pattern: Imperative Shell
2	//
3	// The shared "which keys may sign a sovereign proof for this account" lookup, behind the three
4	// passwordless auth surfaces (`POST /v1/sessions/sovereign`, `POST /oauth/authorize/approve`,
5	// and the deletion-proof branch of `POST /xrpc/com.atproto.server.deleteAccount`).
6	// Signature verification is already method-agnostic (`crypto::verify_did_key_signature` over a
7	// `did:key:` URI, P-256 and secp256k1), so the authority lookup is the only place a DID method
8	// matters. It lives here rather than in either route because routes may not import one another.
9	//
10	// Both methods resolve their authority **live** from the authoritative source, never from the
11	// `did_documents` cache — for did:plc because `rotationKeys` is authoritative only in the latest
12	// non-nullified audit-log operation, and for did:web because that cache is writable by
13	// `POST /v1/did-web/document`.
14	
15	use common::ApiError;
16	use serde_json::Value;
17	
18	use crate::app::AppState;
19	
20	use super::plc::fetch_current_plc_state;
21	use super::resolution::resolve_web_did_document;
22	
23	/// The set of `did:key:` URIs currently authorized to sign a sovereign proof for an account, the
24	/// handles that same authority state asserts, plus a short description of where it was read from
25	/// (for the success log).
26	pub struct AuthoritySet {
27	    keys: Vec<String>,
28	    handles: Vec<String>,
29	    pub source: String,
30	}
31	
32	impl AuthoritySet {
33	    pub fn authorizes(&self, signing_key: &str) -> bool {
34	        self.keys.iter().any(|key| key == signing_key)
35	    }
36	
37	    /// Whether the account's authoritative state asserts `handle` in its `alsoKnownAs`.
38	    ///
39	    /// `handle` must already be ASCII-lowercased; the stored set is normalized on the way in, so
40	    /// the comparison is case-insensitive as atproto handles require.
41	    ///
42	    /// This is only the *assertion* half of the atproto bidirectional handle rule. `alsoKnownAs` is
43	    /// writable by whoever controls the DID, so any account can claim any handle here; a caller
44	    /// binding a client-supplied handle to this account must also confirm the handle resolves back
45	    /// to the DID.
46	    pub fn asserts_handle(&self, handle: &str) -> bool {
47	        self.handles.iter().any(|candidate| candidate == handle)
48	    }
49	}
50	
51	/// Bare, ASCII-lowercased handles from a document's `alsoKnownAs` aliases. Non-`at://` aliases are
52	/// not handles and are dropped rather than compared as-is.
53	///
54	/// The case fold is load-bearing rather than cosmetic: `alsoKnownAs` is hand-authored — a did:web's
55	/// document especially — so an account's asserted handle can carry any case, while atproto handles
56	/// bind case-insensitively. Normalizing only the caller's side would silently refuse a legitimate
57	/// binding whose document happens not to be lowercase.
58	fn asserted_handles<'a>(aliases: impl Iterator<Item = &'a str>) -> Vec<String> {
59	    aliases
60	        .filter_map(|alias| alias.strip_prefix("at://"))
61	        .map(str::to_ascii_lowercase)
62	        .collect()
63	}
64	
65	/// A failed authority lookup, split by who the caller should blame.
66	pub enum AuthorityError {
67	    /// The DID method, document, or policy denies any authority. The caller collapses this into
68	    /// its own opaque rejection — it must never become a distinguishable response.
69	    Unauthorized(&'static str),
70	    /// The authoritative source could not be consulted. Propagated as-is so an upstream outage
71	    /// still fails closed with its own status (a plc.directory 503 stays a 502, not a 401).
72	    Lookup(ApiError),
73	}
74	
75	fn is_plc_did(value: &str) -> bool {
76	    let Some(suffix) = value.strip_prefix("did:plc:") else {
77	        return false;
78	    };
79	    suffix.len() == 24
80	        && suffix
81	            .bytes()
82	            .all(|byte| byte.is_ascii_lowercase() || (b'2'..=b'7').contains(&byte))
83	}
84	
85	/// Resolve the account's current signing authority from its DID method's authoritative source.
86	pub async fn authorized_signing_keys(
87	    state: &AppState,
88	    did: &str,
89	) -> Result<AuthoritySet, AuthorityError> {
90	    if is_plc_did(did) {
91	        plc_authority(state, did).await
92	    } else if did.starts_with("did:web:") {
93	        web_authority(state, did).await
94	    } else {
95	        Err(AuthorityError::Unauthorized("unsupported_did_method"))
96	    }
97	}
98	
99	/// did:plc — every key in the DID's current `rotationKeys`. A Custos-held rotation key qualifies
100	/// under exactly the same PLC semantics as any other, granting Custos no power over an account it
101	/// already hosts: rewriting the rotation set requires an existing rotation key, and plc.directory
102	/// is external to this server.
103	async fn plc_authority(state: &AppState, did: &str) -> Result<AuthoritySet, AuthorityError> {
104	    let plc = fetch_current_plc_state(&state.http_client, &state.config.plc_directory_url, did)
105	        .await
106	        .map_err(AuthorityError::Lookup)?;
107	    Ok(AuthoritySet {
108	        keys: plc.rotation_keys,
109	        handles: asserted_handles(plc.also_known_as.iter().map(String::as_str)),
110	        source: format!("plc:{}", plc.cid),
111	    })
112	}
113	
114	/// did:web — exactly the document's `{did}#device` verification method, and nothing else.
115	///
116	/// Not "any verificationMethod": `#atproto`'s private key is Custos-held, so a broader set would
117	/// let this server sign its own sovereign envelope for an account it hosts. `#device` alone also
118	/// keeps one rule across both did:web paths — `create_did.rs` already enforces `#device`
119	/// specifically when promoting a new did:web.
120	///
121	/// Gated on self-hosted only. `POST /v1/did-web/document` lets an account rewrite its served
122	/// document under mere session auth, so for a Custos-hosted did:web a stolen session could install
123	/// an attacker `#device` key and bootstrap sovereign sessions — a privilege escalation with no key
124	/// compromise. That route already refuses unless hosting is enabled, so
125	/// `did_web_hosting_enabled_at IS NULL` **is** the condition "no session-authed rewrite is
126	/// possible", with no gap in either direction. Making `#device` immutable across such an edit
127	/// would let this gate be dropped later without redesigning anything.
128	async fn web_authority(state: &AppState, did: &str) -> Result<AuthoritySet, AuthorityError> {
129	    // Cheap DB gate before the outbound fetch.
130	    if crate::db::dids::did_web_hosting_enabled(&state.db, did)
131	        .await
132	        .map_err(AuthorityError::Lookup)?
133	    {
134	        return Err(AuthorityError::Unauthorized("did_web_hosting_enabled"));
135	    }
136	
137	    let document = resolve_web_did_document(state, did)
138	        .await
139	        .map_err(AuthorityError::Lookup)?;
140	    let device_key = device_verification_key(&document, did)?;
141	    let handles = asserted_handles(
142	        document
143	            .get("alsoKnownAs")
144	            .and_then(Value::as_array)
145	            .into_iter()
146	            .flatten()
147	            .filter_map(Value::as_str),
148	    );
149	    Ok(AuthoritySet {
150	        keys: vec![device_key],
151	        handles,
152	        source: "did:web#device".to_string(),
153	    })
154	}
155	
156	/// Extract the document's `#device` key as a `did:key:` URI, matching `create_did.rs`'s predicate
157	/// (`type == "Multikey"`, `controller == did`, exact `{did}#device` id). The difference in shape:
158	/// `create_did.rs` *verifies* a known key by comparing `publicKeyMultibase`, whereas this
159	/// *discovers* it, so it extracts that field instead — rendered as `did:key:{multibase}`, since the
160	/// verification method carries bare multibase while a PLC rotation set stores `did:key:` URIs.
161	///
162	/// More than one `#device`-shaped entry is malformed (duplicate `id` values already violate DID
163	/// Core) and fails closed rather than picking one by array order.
164	fn device_verification_key(document: &Value, did: &str) -> Result<String, AuthorityError> {
165	    let expected_id = format!("{did}#device");
166	    let methods = document
167	        .get("verificationMethod")
168	        .and_then(Value::as_array)
169	        .ok_or(AuthorityError::Unauthorized("no_verification_methods"))?;
170	    let mut matches = methods.iter().filter(|method| {
171	        method.get("id").and_then(Value::as_str) == Some(&expected_id)
172	            && method.get("type").and_then(Value::as_str) == Some("Multikey")
173	            && method.get("controller").and_then(Value::as_str) == Some(did)
174	    });
175	    let Some(method) = matches.next() else {
176	        return Err(AuthorityError::Unauthorized(
177	            "no_device_verification_method",
178	        ));
179	    };
180	    if matches.next().is_some() {
181	        return Err(AuthorityError::Unauthorized(
182	            "duplicate_device_verification_method",
183	        ));
184	    }
185	    let multibase = method
186	        .get("publicKeyMultibase")
187	        .and_then(Value::as_str)
188	        .ok_or(AuthorityError::Unauthorized("device_key_not_multibase"))?;
189	    Ok(format!("did:key:{multibase}"))
190	}
191	
192	#[cfg(test)]
193	mod tests {
194	    use super::*;
195	    use serde_json::json;
196	
197	    const WEB_DID: &str = "did:web:example.com";
198	
199	    fn document(methods: Value) -> Value {
200	        json!({ "id": WEB_DID, "verificationMethod": methods })
201	    }
202	
203	    fn device_method(multibase: &str) -> Value {
204	        json!({
205	            "id": format!("{WEB_DID}#device"),
206	            "type": "Multikey",
207	            "controller": WEB_DID,
208	            "publicKeyMultibase": multibase
209	        })
210	    }
211	
212	    fn key(document: &Value) -> Result<String, AuthorityError> {
213	        device_verification_key(document, WEB_DID)
214	    }
215	
216	    fn reason(result: Result<String, AuthorityError>) -> &'static str {
217	        match result {
218	            Err(AuthorityError::Unauthorized(reason)) => reason,
219	            _ => panic!("expected an Unauthorized rejection"),
220	        }
221	    }
222	
223	    #[test]
224	    fn device_method_is_rendered_as_a_did_key_uri() {
225	        let doc = document(json!([device_method("zDevice")]));
226	        assert_eq!(key(&doc).ok().as_deref(), Some("did:key:zDevice"));
227	    }
