240	    #[test]
241	    fn a_duplicate_device_entry_fails_closed_instead_of_picking_by_order() {
242	        let doc = document(json!([device_method("zFirst"), device_method("zSecond")]));
243	        assert_eq!(reason(key(&doc)), "duplicate_device_verification_method");
244	    }
