246	    #[test]
247	    fn a_device_entry_failing_any_predicate_field_is_not_authority() {
248	        for method in [
249	            json!({"id": format!("{WEB_DID}#device"), "type": "JsonWebKey2020", "controller": WEB_DID, "publicKeyMultibase": "zDevice"}),
250	            json!({"id": format!("{WEB_DID}#device"), "type": "Multikey", "controller": "did:web:attacker.example", "publicKeyMultibase": "zDevice"}),
251	            json!({"id": "did:web:other.example#device", "type": "Multikey", "controller": WEB_DID, "publicKeyMultibase": "zDevice"}),
252	        ] {
253	            assert_eq!(
254	                reason(key(&document(json!([method])))),
255	                "no_device_verification_method"
256	            );
257	        }
258	    }
