260	    #[test]
261	    fn a_device_entry_without_a_multibase_key_is_rejected() {
262	        let doc = document(json!([{
263	            "id": format!("{WEB_DID}#device"),
264	            "type": "Multikey",
265	            "controller": WEB_DID
266	        }]));
267	        assert_eq!(reason(key(&doc)), "device_key_not_multibase");
268	    }
