81	test('a full flow issues a DPoP-bound session and reaches an authenticated endpoint', async () => {
82	  const key = await generateDpopKey();
83	  const { verifier, challenge } = pkce();
84	
85	  // ── Pushed authorization request ────────────────────────────────────────────
86	  const pushed = await par(metadata, {
87	    client_id: CLIENT_ID,
88	    redirect_uri: REDIRECT_URI,
89	    response_type: 'code',
90	    code_challenge: challenge,
91	    code_challenge_method: 'S256',
92	    scope: 'atproto transition:generic',
93	    state: 'conformance-state',
94	  });
95	  assert.equal(pushed.status, 201, `PAR must succeed, got ${pushed.status}: ${pushed.text}`);
96	  const requestUri = pushed.json.request_uri as string;
97	  assert.ok(requestUri, 'PAR must return a request_uri');
98	
99	  // ── Consent ─────────────────────────────────────────────────────────────────
100	  const authorizeUrl =
101	    `${metadata.authorization_endpoint}?client_id=${encodeURIComponent(CLIENT_ID)}` +
102	    `&request_uri=${encodeURIComponent(requestUri)}`;
103	  const approval = await approveConsent(fixture.baseUrl, authorizeUrl, {
104	    identifier: fixture.account.did,
105	    password: fixture.account.password,
106	  });
107	
108	  const code = approval.params.get('code');
109	  assert.ok(code, `authorization response must carry a code: ${approval.location}`);
110	  assert.equal(
111	    approval.params.get('state'),
112	    'conformance-state',
113	    'state must round-trip to the client',
114	  );
115	  assert.equal(
116	    approval.params.get('iss'),
117	    metadata.issuer,
118	    'RFC 9207: the authorization response must identify the issuer',
119	  );
120	
121	  // ── Token exchange ──────────────────────────────────────────────────────────
122	  const exchange = await tokenRequestWithNonceRetry(metadata, key, {
123	    grant_type: 'authorization_code',
124	    code,
125	    redirect_uri: REDIRECT_URI,
126	    client_id: CLIENT_ID,
127	    code_verifier: verifier,
128	  });
129	
130	  // The nonce dance is the single most common hand-rolled-client failure: assert the server
131	  // both demanded a nonce and supplied one to retry with.
132	  assert.ok(exchange.challenge, 'the first token request should be challenged for a nonce');
133	  assert.equal(exchange.challenge.json.error, 'use_dpop_nonce');
134	  assert.ok(
135	    exchange.challenge.headers.get('dpop-nonce'),
136	    'a use_dpop_nonce challenge must carry the DPoP-Nonce header, or the client cannot retry',
137	  );
138	
139	  const token = exchange.final;
140	  assert.equal(token.status, 200, `token exchange must succeed: ${token.text}`);
141	
142	  // REGRESSION: the atproto profile requires the account DID in `sub`. Omitting it 500'd
143	  // tangled.org's callback (see project memory: oauth-token-sub-did).
144	  assert.equal(
145	    token.json.sub,
146	    fixture.account.did,
147	    'the token response must carry the account DID in sub',
148	  );
149	  assert.equal(token.json.token_type, 'DPoP', 'atproto tokens are DPoP-bound, never Bearer');
150	  assert.ok(token.json.refresh_token, 'a refresh token must be issued');
151	
152	  // REGRESSION: 300-second access tokens killed real sessions minutes after login.
153	  assert.ok(
154	    token.json.expires_in >= 600,
155	    `access tokens must live at least 10 minutes, got ${token.json.expires_in}s`,
156	  );
