158	  // The access token must be bound to the key that redeemed the code.
159	  const claims = decodeJwtPayload(token.json.access_token);
160	  assert.equal(claims.sub, fixture.account.did, 'the JWT sub must match the response sub');
161	  assert.equal(claims.cnf?.jkt, key.thumbprint, 'the token must be bound to the DPoP key');
162	
163	  // ── Authenticated call ──────────────────────────────────────────────────────
164	  const session = await xrpc(
165	    fixture.baseUrl,
166	    'com.atproto.server.getSession',
167	    key,
168	    token.json.access_token,
169	  );
170	  assert.equal(session.status, 200, `an authenticated call must succeed: ${session.text}`);
171	  assert.equal(session.json.did, fixture.account.did);
172	});
