266	  // consent path, which keeps its pending request server-side — and that path has no coverage
267	  // here yet (MM-502). Until it does, the binding is exercised end-to-end nowhere, and the
268	  // enforcement itself is covered only by the Rust test
269	  // `authorization_code_bound_to_another_dpop_key_is_rejected`, which writes the binding
270	  // directly onto the code row.
271	  //
272	  // This test exists so that stops being invisible: if the password path ever starts binding,
273	  // it fails and someone updates it deliberately.
274	  const flowKey = await generateDpopKey();
275	  const otherKey = await generateDpopKey();
276	  const { verifier, challenge } = pkce();
277	
278	  const pushed = await par(
279	    metadata,
280	    {
281	      client_id: CLIENT_ID,
