298	  );
299	  const code = approval.params.get('code');
300	  assert.ok(code, `consent must yield a code: ${approval.location}`);
301	
302	  const redeemed = await tokenRequestWithNonceRetry(metadata, otherKey, {
303	    grant_type: 'authorization_code',
304	    code,
305	    redirect_uri: REDIRECT_URI,
306	    client_id: CLIENT_ID,
307	    code_verifier: verifier,
308	  });
