3	//! Shared did:plc rotation/update-op machinery for the PDS-signed interop migration surface
4	//! (ADR-0002), used by the `identity.*PlcOperation` routes: read a DID's current PLC state from
5	//! plc.directory (an audit-log GET — the one Imperative Shell function here) so the PDS can
6	//! build the next operation on top of it, render an updated DID document from an operation's
7	//! fields, parse request `verificationMethods`/`services`, and `ensure_did_plc` (reject a
8	//! non-`did:plc` account with an explicit 400 before any plc.directory work). Everything but the
9	//! audit-log fetch is pure construction.
10	//!
11	//! The wallet-authorized path does NOT use these — it builds and submits its identity leg
12	//! locally with the device key. These endpoints exist so off-the-shelf tooling can migrate off
13	//! ezpds and so ezpds can serve as a migration destination.
14	
15	use std::collections::BTreeMap;
16	
17	use common::{ApiError, ErrorCode};
18	use serde::Deserialize;
19	
20	/// Reject a DID whose method is not `did:plc`.
21	///
22	/// The `identity.*PlcOperation` endpoints only make sense for a `did:plc` identity — they build,
23	/// sign, and submit operations against plc.directory's hash-linked operation log. A `did:web`
24	/// identity (the operator hosts its own `did.json`; see ADR-0003) has no PLC log at all, so
25	/// calling these endpoints for one would otherwise fail confusingly deep in the flow — a 404 on
26	/// the plc.directory audit-log fetch. Guard the method up front instead, returning an explicit
27	/// "not a did:plc" error the caller can act on: a did:web account repoints its PDS by editing its
28	/// own `did.json`, not by signing a PLC operation.
29	pub fn ensure_did_plc(did: &str) -> Result<(), ApiError> {
30	    if did.starts_with("did:plc:") {
31	        Ok(())
32	    } else {
33	        Err(ApiError::new(
34	            ErrorCode::InvalidRequest,
35	            "this account is not a did:plc identity; PLC operations do not apply. \
36	             A did:web identity is repointed by editing its own did.json, not by signing a \
37	             PLC operation.",
38	        ))
39	    }
40	}
41	
42	/// A DID's current PLC state, distilled from its latest non-nullified audit-log
43	/// entry. `cid` is the head operation's CID — the `prev` of the next operation.
44	#[derive(Debug)]
45	pub struct CurrentPlcState {
46	    pub cid: String,
47	    pub rotation_keys: Vec<String>,
48	    pub verification_methods: BTreeMap<String, String>,
49	    pub also_known_as: Vec<String>,
50	    pub services: BTreeMap<String, crypto::PlcService>,
51	}
52	
53	/// The mutable fields of a `plc_operation`, as they appear in a plc.directory
54	/// audit-log entry's `operation` object (and in a `signPlcOperation` request body).
55	#[derive(Deserialize)]
56	struct PlcOpFields {
57	    #[serde(rename = "rotationKeys", default)]
58	    rotation_keys: Vec<String>,
59	    #[serde(rename = "verificationMethods", default)]
60	    verification_methods: BTreeMap<String, String>,
61	    #[serde(rename = "alsoKnownAs", default)]
62	    also_known_as: Vec<String>,
63	    #[serde(default)]
64	    services: BTreeMap<String, crypto::PlcService>,
65	}
66	
67	/// Fetch a DID's current PLC state from `{plc_directory_url}/{did}/log/audit`.
68	///
69	/// Returns the most recent **non-nullified** operation's CID and mutable fields.
70	/// The caller uses `cid` as the next operation's `prev` and the fields as the
71	/// defaults that a `signPlcOperation` request overlays its changes onto.
72	///
73	/// # Errors
74	/// - `PlcDirectoryError` if plc.directory is unreachable or returns non-success.
75	/// - `DidNotFound` if the audit log is empty or every entry is nullified.
76	/// - `InternalError` if the response is not parseable as an audit log / operation.
77	pub async fn fetch_current_plc_state(
78	    http_client: &reqwest::Client,
79	    plc_directory_url: &str,
80	    did: &str,
81	) -> Result<CurrentPlcState, ApiError> {
82	    let url = format!("{plc_directory_url}/{did}/log/audit");
83	    let response = http_client.get(&url).send().await.map_err(|e| {
84	        tracing::error!(error = %e, url = %url, "failed to contact plc.directory for audit log");
85	        ApiError::new(
86	            ErrorCode::PlcDirectoryError,
87	            "failed to contact plc.directory",
88	        )
89	    })?;
90	
91	    if !response.status().is_success() {
92	        let status = response.status();
93	        tracing::warn!(status = %status, did = %did, "plc.directory audit log request failed");
94	        return Err(ApiError::new(
95	            ErrorCode::PlcDirectoryError,
96	            format!("plc.directory returned {status} for the audit log"),
97	        ));
98	    }
99	
100	    let body = response.text().await.map_err(|e| {
101	        tracing::error!(error = %e, "failed to read plc.directory audit log body");
102	        ApiError::new(
103	            ErrorCode::PlcDirectoryError,
104	            "failed to read plc.directory response",
105	        )
106	    })?;
107	
108	    let entries = crypto::parse_audit_log(&body).map_err(|e| {
109	        tracing::error!(error = %e, "failed to parse plc.directory audit log");
110	        ApiError::new(ErrorCode::InternalError, "failed to parse PLC audit log")
111	    })?;
112	
113	    // The current state is the newest operation that plc.directory has not nullified.
114	    let head = entries.iter().rev().find(|e| !e.nullified).ok_or_else(|| {
115	        ApiError::new(
116	            ErrorCode::DidNotFound,
117	            "no active PLC operation found for this DID",
118	        )
119	    })?;
120	
121	    let fields: PlcOpFields = serde_json::from_value(head.operation.clone()).map_err(|e| {
122	        tracing::error!(error = %e, "PLC audit-log operation is not a recognised plc_operation");
123	        ApiError::new(
124	            ErrorCode::InternalError,
125	            "unexpected PLC operation shape in audit log",
126	        )
127	    })?;
128	
129	    Ok(CurrentPlcState {
130	        cid: head.cid.clone(),
131	        rotation_keys: fields.rotation_keys,
132	        verification_methods: fields.verification_methods,
133	        also_known_as: fields.also_known_as,
134	        services: fields.services,
135	    })
136	}
137	
138	/// Render a minimal DID Core document from a PLC operation's fields.
139	///
140	/// Used to refresh the locally-cached DID document after a self-submitted PLC
141	/// operation repoints the identity (`submitPlcOperation`). Mirrors the shape
142	/// `genesis::build_did_document` produces for a genesis op.
143	///
144	/// # Errors
145	/// Returns `InternalError` if `verificationMethods["atproto"]` is absent or not a
146	/// `did:key:` URI, or if there is no `atproto_pds` service endpoint.
147	pub fn build_did_document_from_op(
148	    did: &str,
149	    verification_methods: &BTreeMap<String, String>,
150	    also_known_as: &[String],
151	    services: &BTreeMap<String, crypto::PlcService>,
152	) -> Result<serde_json::Value, ApiError> {
153	    let atproto_did_key = verification_methods.get("atproto").ok_or_else(|| {
154	        ApiError::new(
155	            ErrorCode::InternalError,
156	            "operation verificationMethods.atproto is missing",
157	        )
158	    })?;
159	    let public_key_multibase = atproto_did_key.strip_prefix("did:key:").ok_or_else(|| {
160	        ApiError::new(
161	            ErrorCode::InternalError,
162	            "operation atproto key is not a did:key: URI",
163	        )
164	    })?;
165	    let service_endpoint = services
166	        .get("atproto_pds")
167	        .map(|s| s.endpoint.as_str())
168	        .ok_or_else(|| {
169	            ApiError::new(
170	                ErrorCode::InternalError,
171	                "operation is missing an atproto_pds service endpoint",
172	            )
173	        })?;
174	
175	    Ok(serde_json::json!({
176	        "@context": ["https://www.w3.org/ns/did/v1"],
177	        "id": did,
178	        "alsoKnownAs": also_known_as,
179	        "verificationMethod": [{
180	            "id": format!("{did}#atproto"),
181	            "type": "Multikey",
182	            "controller": did,
183	            "publicKeyMultibase": public_key_multibase
184	        }],
185	        "service": [{
186	            "id": "#atproto_pds",
187	            "type": "AtprotoPersonalDataServer",
188	            "serviceEndpoint": service_endpoint
189	        }]
190	    }))
191	}
192	
193	/// Deserialize a request-supplied `verificationMethods` JSON object into the map
194	/// shape the PLC op builder expects. Returns `InvalidRequest` on a malformed value.
195	pub fn parse_verification_methods(
196	    value: &serde_json::Value,
197	) -> Result<BTreeMap<String, String>, ApiError> {
198	    serde_json::from_value(value.clone()).map_err(|e| {
199	        tracing::warn!(error = %e, "invalid verificationMethods in request");
200	        ApiError::new(
201	            ErrorCode::InvalidRequest,
202	            "verificationMethods must be a map of method name to did:key URI",
203	        )
204	    })
205	}
206	
207	/// Deserialize a request-supplied `services` JSON object into the map shape the
208	/// PLC op builder expects. Returns `InvalidRequest` on a malformed value.
209	pub fn parse_services(
210	    value: &serde_json::Value,
