1	// P-256 key handling and did:plc genesis-op construction. ezpds never mints a
2	// server-custodied DID: the client builds and signs the genesis operation itself
3	// (rotationKeys[0] = our locally-held rotation key), so the private keys the CLI
4	// generates here are the real root of control for test accounts — they are
5	// persisted in the local state file and must never be committed.
6	
7	import * as crypto from 'node:crypto';
8	import * as dagCbor from '@ipld/dag-cbor';
9	import { P256Keypair } from '@atproto/crypto';
10	
11	const BASE32_ALPHABET = 'REDACTED';
12	
13	function base32Encode(buffer) {
14	  let result = '';
15	  let bits = 0;
16	  let value = 0;
17	  for (const byte of buffer) {
18	    value = (value << 8) | byte;
19	    bits += 8;
20	    while (bits >= 5) {
21	      result += BASE32_ALPHABET[(value >>> (bits - 5)) & 0x1f];
22	      bits -= 5;
23	    }
24	  }
25	  if (bits > 0) result += BASE32_ALPHABET[(value << (5 - bits)) & 0x1f];
26	  return result;
27	}
28	
29	/** Generate a fresh exportable P-256 keypair. */
30	export async function newKeypair() {
31	  const keypair = await P256Keypair.create({ exportable: true });
32	  const exported = await keypair.export();
33	  const privateKey = exported instanceof Uint8Array ? exported : exported.bytes ?? exported;
34	  return {
35	    keypair,
36	    keyId: keypair.did(), // did:key:zDn...
37	    privateKeyHex: Buffer.from(privateKey).toString('hex'),
38	    publicKeyBase64: Buffer.from(keypair.publicKeyBytes()).toString('base64'),
39	  };
40	}
41	
42	/** Rehydrate a keypair from the hex private key stored in the state file. */
43	export async function keypairFromHex(privateKeyHex) {
44	  return P256Keypair.import(privateKeyHex, { exportable: true });
45	}
46	
47	/**
48	 * Sign a did:plc operation (genesis or migration) with a rotation keypair.
49	 *
50	 * The signing primitive shared by every PLC op: DAG-CBOR encode the unsigned op,
51	 * sign those bytes with the rotation key, and append the signature as base64url.
52	 * Returns the signed op (all unsigned fields plus `sig`). This is the single
53	 * source of truth for PLC signing — genesis and migration both consume it, so
54	 * the two paths cannot silently diverge.
55	 */
56	export async function signPlcOp(unsignedOp, rotationKeypair) {
57	  const unsignedBytes = dagCbor.encode(unsignedOp);
58	  const signature = await rotationKeypair.sign(unsignedBytes);
59	  return { ...unsignedOp, sig: Buffer.from(signature).toString('base64url') };
60	}
61	
62	/**
63	 * Build and sign a did:plc genesis operation for the client-share ceremony.
64	 *
65	 * rotationKeys = [rotation, recovery, PDS] (the recovery slot mirrors the wallet's
66	 * client-share ceremony: the device/rotation key stays highest-priority, the
67	 * wallet-derived recovery key sits in the middle, the PDS repo signing key last):
68	 *   rotationKeys[0] = the locally-held rotation key (signs this op),
69	 *   rotationKeys[1] = the recovery rotation key (its did:key is declared as
70	 *                     `recoveryKey` to POST /v1/dids; the server verifies it appears here),
71	 *   rotationKeys[2] = the PDS-issued per-account repo signing key, which is also
72	 *                     verificationMethods.atproto (it signs repo commits on the PDS).
73	 *
74	 * Returns the derived DID (`did:plc:` + first 24 chars of base32(sha256(signed
75	 * op DAG-CBOR))) and the signed op as a JSON-ready object.
76	 */
77	export async function buildGenesisOp({
78	  rotationKeyId,
79	  recoveryKeyId,
80	  repoSigningKeyId,
81	  rotationKeypair,
82	  handle,
83	  pdsUrl,
84	}) {
85	  const unsignedOp = {
86	    prev: null,
87	    type: 'plc_operation',
88	    services: {
89	      atproto_pds: {
90	        type: 'AtprotoPersonalDataServer',
91	        endpoint: pdsUrl,
92	      },
93	    },
94	    alsoKnownAs: [`at://${handle}`],
95	    rotationKeys: [rotationKeyId, recoveryKeyId, repoSigningKeyId],
96	    verificationMethods: {
97	      atproto: repoSigningKeyId,
98	    },
99	  };
100	
101	  const signedOp = await signPlcOp(unsignedOp, rotationKeypair);
102	
103	  const signedBytes = dagCbor.encode(signedOp);
104	  const hash = crypto.createHash('sha256').update(signedBytes).digest();
105	  const did = `did:plc:${base32Encode(hash).slice(0, 24)}`;
106	
107	  return { did, signedOp };
108	}
109	
110	/**
111	 * Build a structurally-valid v2 Shamir Share 2 envelope for the client-share
112	 * `escrowShare` field of POST /v1/dids.
113	 *
114	 * The server (crates/crypto `ShareEnvelope::decode_share`) validates only the
115	 * envelope's structure — version, index, and trailing checksum — and that the index
116	 * is 2; it never reconstructs a secret from it. The interop harness provisions
117	 * accounts to exercise other surfaces and does not test recovery, so a fresh random
118	 * payload under a random set_id is sufficient (the recovery key in `rotationKeys`
119	 * is likewise an independent keypair). The wire layout mirrors the Rust envelope:
120	 * `version(1)=2 || set_id(4 BE) || index(1)=2 || payload(32) || checksum(4 =
121	 * sha256(preceding 38)[..4])`, uppercase base32 (RFC 4648, no padding).
122	 */
123	export function encodeEscrowShare() {
124	  const preimage = Buffer.alloc(38);
125	  preimage.writeUInt8(2, 0); // version
126	  crypto.randomBytes(4).copy(preimage, 1); // set_id (4B big-endian; random bytes are fine)
127	  preimage.writeUInt8(2, 5); // index — the escrow slot holds Share 2 only
128	  crypto.randomBytes(32).copy(preimage, 6); // payload
129	  const checksum = crypto.createHash('sha256').update(preimage).digest().subarray(0, 4);
130	  const envelope = Buffer.concat([preimage, checksum]); // 42 bytes
131	  return base32Encode(envelope).toUpperCase();
132	}
133	
134	/** Cryptographically random password suitable for a test account. */
135	export function randomPassword() {
136	  return crypto.randomBytes(18).toString('base64url'); // 24 chars
137	}
138	
139	/** Short random suffix for handles/names. */
140	export function randomSuffix(len = 6) {
141	  return crypto.randomBytes(8).toString('base64url').replace(/[^a-z0-9]/gi, '').toLowerCase().slice(0, len).padEnd(len, '0');
142	}
