1	// The consent seam: drives the PDS's password consent page the way a browser would.
2	//
3	// An authorization-code flow needs a human to approve at the authorization server. Since the
4	// server under test is ours and its consent page is a plain password form, the suite fills
5	// that form directly instead of running a browser.
6	//
7	// This file is the ONLY place that knows the page's markup. Every test goes through
8	// `approveConsent`, so a change to the page is a one-line fix here rather than a diff across
9	// the whole suite — and when the markup does change, `parseConsentForm` throws a message
10	// naming itself, instead of failing later as a confusing "missing parameter" from the server.
11	//
12	// Rejected alternative: a test-only auto-approve endpoint. It would be immune to markup
13	// changes, but it would exercise a code path no real client takes — which is the exact
14	// failure mode (testing our own assumptions instead of the real contract) that the audit
15	// this suite came from was about.
16	
17	/** The hidden fields the consent form round-trips, plus the scope checkboxes. */
18	export interface ConsentFormFields {
19	  hidden: Record<string, string>;
20	  /** One value per `granted_scope` checkbox rendered on the page. */
21	  grantedScopes: string[];
22	}
23	
24	function decodeEntities(value: string): string {
25	  return value
26	    .replace(/&quot;/g, '"')
27	    .replace(/&#39;/g, "'")
28	    .replace(/&lt;/g, '<')
29	    .replace(/&gt;/g, '>')
30	    .replace(/&amp;/g, '&');
31	}
32	
33	/**
34	 * Extract the consent form's fields from the rendered page.
35	 *
36	 * Parses by `name=`/`value=` attribute rather than by position or surrounding markup, so
37	 * restyling the page does not break the suite; only renaming a field does, which is a real
38	 * contract change worth failing on.
39	 */
40	export function parseConsentForm(html: string): ConsentFormFields {
41	  const hidden: Record<string, string> = {};
42	  const hiddenPattern =
43	    /<input[^>]*type="hidden"[^>]*name="([^"]+)"[^>]*value="([^"]*)"[^>]*>/g;
44	  for (const match of html.matchAll(hiddenPattern)) {
45	    const [, name, value] = match;
46	    if (name !== undefined) hidden[name] = decodeEntities(value ?? '');
47	  }
48	
49	  const grantedScopes: string[] = [];
50	  const checkboxPattern = /<input[^>]*name="granted_scope"[^>]*value="([^"]*)"[^>]*>/g;
51	  for (const match of html.matchAll(checkboxPattern)) {
52	    const [, value] = match;
53	    if (value !== undefined) grantedScopes.push(decodeEntities(value));
54	  }
55	
56	  if (!hidden.client_id || !hidden.redirect_uri || !hidden.code_challenge) {
57	    throw new Error(
58	      'consent page markup no longer matches what tools/oauth-conformance/src/consent.ts ' +
59	        'expects: could not find the hidden client_id/redirect_uri/code_challenge inputs. ' +
60	        'If the consent page was legitimately changed, update parseConsentForm() here — ' +
61	        'this is the single place the suite knows the page markup.\n' +
62	        `Received ${html.length} bytes starting: ${html.slice(0, 200)}`,
63	    );
64	  }
65	  return { hidden, grantedScopes };
66	}
67	
68	export interface ApprovalResult {
69	  status: number;
70	  /** The `Location` header of the redirect back to the client. */
71	  location: string;
72	  /** Authorization-response parameters, read from the query or the fragment. */
73	  params: URLSearchParams;
74	}
75	
76	/** Read the authorization response parameters from a redirect, in either response mode. */
77	export function parseAuthorizationRedirect(location: string): URLSearchParams {
78	  const url = new URL(location);
79	  // A fragment-mode response puts everything after '#'; query mode uses the search string.
80	  return url.hash ? new URLSearchParams(url.hash.slice(1)) : url.searchParams;
81	}
82	
83	/**
84	 * Approve (or deny) an authorization request as the account owner.
85	 *
86	 * `grantedScopes` defaults to every checkbox the page offered — i.e. the user approving
87	 * everything asked for. Passing a narrower list simulates a user unchecking permissions,
88	 * which is how a scope-narrowing test is written.
89	 */
90	export async function approveConsent(
91	  baseUrl: string,
92	  authorizeUrl: string,
93	  credentials: { identifier: string; password: string },
94	  opts: { decision?: 'approve' | 'deny'; grantedScopes?: string[] } = {},
95	): Promise<ApprovalResult> {
96	  const pageRes = await fetch(authorizeUrl);
97	  const html = await pageRes.text();
98	  if (pageRes.status !== 200) {
99	    throw new Error(
100	      `consent page returned ${pageRes.status} (expected 200). Body: ${html.slice(0, 400)}`,
101	    );
102	  }
103	  const form = parseConsentForm(html);
104	
105	  const body = new URLSearchParams();
106	  for (const [name, value] of Object.entries(form.hidden)) body.append(name, value);
107	  body.append('identifier', credentials.identifier);
108	  body.append('password', credentials.password);
109	  body.append('action', opts.decision ?? 'approve');
110	  for (const scope of opts.grantedScopes ?? form.grantedScopes) {
111	    body.append('granted_scope', scope);
112	  }
113	
114	  // `redirect: 'manual'` is essential: the authorization response *is* the redirect, and
115	  // following it would send the code to a callback URL that nothing is listening on.
116	  const res = await fetch(`${baseUrl}/oauth/authorize`, {
117	    method: 'POST',
118	    headers: { 'content-type': 'application/x-www-form-urlencoded' },
119	    body: body.toString(),
120	    redirect: 'manual',
121	  });
122	  const location = res.headers.get('location');
123	  if (!location) {
124	    const text = await res.text();
125	    throw new Error(
126	      `consent POST did not redirect (status ${res.status}); the credentials may have been ` +
127	        `rejected. Body: ${text.slice(0, 400)}`,
128	    );
129	  }
130	  return { status: res.status, location, params: parseAuthorizationRedirect(location) };
131	}
132

            &params.redirect_uri,
            "unsupported_response_type",
            "only response_type=code is supported",
            &params.state,
