function jwtExpiresSoon(jwt, marginSeconds = 60) {
  try {
    const payload = JSON.parse(Buffer.from(jwt.split('.')[1], 'base64url').toString('utf8'));
    return payload.exp * 1000 < Date.now() + marginSeconds * 1000;
  } catch {
    return true;
  }
