    rotationKeyId: account.rotationKeyId,
    recoveryKeyId: account.recoveryKeyId,
    repoSigningKeyId: account.repoSigningKeyId,
    rotationKeypair: await keypairFromHex(account.rotationKeyPrivateHex),
